node --input-type=module -e '
import { readFileSync } from "node:fs";
let src = readFileSync("/output/lib/toc.mjs", "utf8");
const importLine = `import { plainTextForInline } from \x27./inline.mjs\x27;`;
if (!src.includes(importLine)) throw new Error("import line not found");
// Stub: plain mode = raw text; toc mode = escape & < >
const stub = `
function plainTextForInline(raw, mode) {
  if (mode === "plain") return String(raw);
  return String(raw).split("&").join("&amp;").split("<").join("&lt;").split(">").join("&gt;");
}
`;
src = src.split(importLine).join(stub);
const mod = await import("data:text/javascript," + encodeURIComponent(src));
const { createTocState, registerHeading, renderToc, isTocMarkerText, slugify } = mod;

let fail = 0;
function eq(actual, expected, label) {
  if (actual !== expected) { fail++; console.log("FAIL " + label); console.log("  actual:   " + JSON.stringify(actual)); console.log("  expected: " + JSON.stringify(expected)); }
  else console.log("ok " + label);
}

// slugify rules
eq(slugify("Hello World"), "hello-world", "slug basic");
eq(slugify("Foo  --   Bar"), "foo-bar", "slug fold hyphen+space run");
eq(slugify("  AT&T's Blog!  "), "atts-blog", "slug strip punct/trim");
eq(slugify("标题 1"), "1", "slug non-ascii dropped");
eq(slugify("café"), "cafe", "slug NFKD");
eq(slugify("a_b-c"), "a_b-c", "slug underscore kept");
eq(slugify("- lead"), "-lead", "slug leading hyphen kept");
eq(slugify(""), "", "slug empty");
eq(slugify("²"), "2", "slug NFKD superscript");

// unique ids
let s = createTocState();
eq(registerHeading(s, 1, "Intro"), "intro", "id first");
eq(registerHeading(s, 2, "Intro"), "intro_1", "id dup");
eq(registerHeading(s, 2, "Intro"), "intro_2", "id dup2");
eq(registerHeading(s, 1, "intro_1"), "intro_1_1", "id numeric suffix continues");
eq(registerHeading(s, 1, "标题"), "_1", "id empty slug");
eq(registerHeading(s, 1, "标题"), "_2", "id empty slug inc");
eq(s.headings.length, 6, "headings recorded");
eq(s.headings[0].level, 1, "level stored");
eq(s.headings[0].textHtml, "Intro", "textHtml stored");

// render empty
eq(renderToc(createTocState()), '<div class="toc">\n<ul></ul>\n</div>', "render empty");

// render nested: A(1) B(2) C(2) D(1) plus E(3) child of D, F(2) sibling pop
let s2 = createTocState();
registerHeading(s2, 1, "A"); registerHeading(s2, 2, "B");
registerHeading(s2, 2, "C"); registerHeading(s2, 1, "D");
const expected2 = '<div class="toc">\n<ul>\n' +
  '<li><a href="#a">A</a><ul>\n' +
  '<li><a href="#b">B</a></li>\n' +
  '<li><a href="#c">C</a></li>\n' +
  '</ul>\n</li>\n' +
  '<li><a href="#d">D</a></li>\n' +
  '</ul>\n</div>';
eq(renderToc(s2), expected2, "render nested A/B/C/D");

// level jump: h1 then h3 (h3 becomes child of h1), then h2 (pops h3, child of h1)
let s3 = createTocState();
registerHeading(s3, 1, "A"); registerHeading(s3, 3, "B"); registerHeading(s3, 2, "C");
const expected3 = '<div class="toc">\n<ul>\n' +
  '<li><a href="#a">A</a><ul>\n' +
  '<li><a href="#b">B</a></li>\n' +
  '<li><a href="#c">C</a></li>\n' +
  '</ul>\n</li>\n' +
  '</ul>\n</div>';
eq(renderToc(s3), expected3, "render level jump");

// starts at h2 with no h1
let s4 = createTocState();
registerHeading(s4, 2, "X & Y");
const expected4 = '<div class="toc">\n<ul>\n<li><a href="#x-y">X &amp; Y</a></li>\n</ul>\n</div>';
eq(renderToc(s4), expected4, "render escaped text");

// marker
eq(isTocMarkerText("[TOC]"), true, "marker exact");
eq(isTocMarkerText("[toc]"), false, "marker lowercase");
eq(isTocMarkerText(" [TOC] "), false, "marker untrimmed");
eq(isTocMarkerText("[TOC]x"), false, "marker suffix");

// output never ends with newline
eq(renderToc(s2).endsWith("\n"), false, "no trailing newline");

console.log(fail === 0 ? "ALL_TESTS_PASSED" : fail + " FAILURES");
process.exit(fail === 0 ? 0 : 1);
'

