import {
  parseFenceOpening,
  findFenceClose,
  renderFencedCode,
  renderIndentedCode,
  escapeHtmlAll,
} from '/output/lib/code.mjs';

let fails = 0;
function eq(name, got, want) {
  if (got === want) {
    console.log('ok   ' + name);
  } else {
    fails++;
    console.log('FAIL ' + name);
    console.log('  got:  ' + JSON.stringify(got));
    console.log('  want: ' + JSON.stringify(want));
  }
}

// --- parseFenceOpening ---
eq('plain fence', JSON.stringify(parseFenceOpening('```')),
  JSON.stringify({char:'`',length:3,fence:'```',lang:null,id:null,preClasses:[],info:''}));
eq('bare lang', parseFenceOpening('```python').lang, 'python');
eq('dotted lang', parseFenceOpening('```.python').lang, 'python');
eq('tilde', parseFenceOpening('~~~js').fence, '~~~');
eq('extra words -> null', parseFenceOpening('~~~js extra words'), null);
eq('indented -> null', parseFenceOpening(' ```python'), null);
eq('2 backticks -> null', parseFenceOpening('``'), null);
eq('attrs', JSON.stringify(parseFenceOpening('```{.python #code .hl}')),
  JSON.stringify({char:'`',length:3,fence:'```',lang:'python',id:'code',preClasses:['hl'],info:'{.python #code .hl}'}));
eq('unknown key ignored', JSON.stringify(parseFenceOpening('```{.html #i .c unknown=1}')),
  JSON.stringify({char:'`',length:3,fence:'```',lang:'html',id:'i',preClasses:['c'],info:'{.html #i .c unknown=1}'}));
eq('unclosed brace -> null', parseFenceOpening('```{.python'), null);
eq('trailing spaces ok', parseFenceOpening('```python  ').lang, 'python');

// --- findFenceClose ---
const lines = ['```python', 'a', '```   ', 'tail'];
eq('close found', findFenceClose(lines, 1, '```'), 2);
eq('close not found', findFenceClose(['```', 'a', '~~~~'], 1, '```'), null);
eq('longer fence not a close', findFenceClose(['```', 'a', '````'], 1, '```'), null);
eq('info object accepted', findFenceClose(lines, 1, parseFenceOpening('```python')), 2);
eq('leading space not allowed', findFenceClose(['```', 'a', ' ```'], 1, '```'), null);

// --- renderFencedCode --- (matches executable output)
eq('fenced python',
  renderFencedCode(parseFenceOpening('```python'), ['print(1)']),
  '<pre><code class="language-python">print(1)\n</code></pre>');
eq('fenced attrs',
  renderFencedCode(parseFenceOpening('```{.python #code .hl}'), ['print(1)']),
  '<pre id="code" class="hl"><code class="language-python">print(1)\n</code></pre>');
eq('fenced html escape',
  renderFencedCode(parseFenceOpening('```{.html #i .c unknown=1}'), ['<b>&']),
  '<pre id="i" class="c"><code class="language-html">&lt;b&gt;&amp;\n</code></pre>');
eq('fenced no lang',
  renderFencedCode(parseFenceOpening('```'), ['empty']),
  '<pre><code>empty\n</code></pre>');
eq('fenced empty no trailing nl',
  renderFencedCode(parseFenceOpening('```'), []),
  '<pre><code></code></pre>');

// --- renderIndentedCode ---
eq('indented default',
  renderIndentedCode('a < b'),
  '<pre><code>a &lt; b\n</code></pre>');
eq('codehilite plain (matches executable)',
  renderIndentedCode('def foo():\n    pass', { codehilite: true }),
  '<div class="codehilite"><pre><span></span><code>def foo():\n    pass\n</code></pre></div>');
eq('codehilite escape quote',
  renderIndentedCode('<b>&amp;"', { codehilite: true }),
  '<div class="codehilite"><pre><span></span><code>&lt;b&gt;&amp;amp;&quot;\n</code></pre></div>');
eq('codehilite :::python (matches executable)',
  renderIndentedCode(':::python\ndef foo():\n    pass', { codehilite: true }),
  '<div class="codehilite"><pre><span></span><code><span class="k">def</span><span class="w"> </span><span class="nf">foo</span><span class="p">():</span>\n    <span class="k">pass</span>\n</code></pre></div>');
eq('codehilite :::foobar plain (matches executable)',
  renderIndentedCode(':::foobar\nhi', { codehilite: true }),
  '<div class="codehilite"><pre><span></span><code>hi\n</code></pre></div>');

console.log(fails === 0 ? 'ALL PASS' : fails + ' FAILURES');
process.exit(fails === 0 ? 0 : 1);

